-- Diana Delgado (profileID=4) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Diana Delgado phrasings

SELECT p.argumentID, p.phrasingID, 4, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 4
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 4 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=4 AND targArgID IN (54,80,88,89,90,94,96,100,101,103,104,105,107,108,109,110,118,120,123,134,135,142,145,148,151,153,154,155,163,165,166,169,171,174,175,182,184,185,192,193,203,204,207,217,218,219,221,230,236,240,241,321,349,350,355,356,357,414,476,477,484,485,494,495,539,546,560,561,603,604,606,609,611,612,616,617,640,666,727,745,785,790,791,795,797,801,836,863,892,972,1143,1159,1160,1188,1197,1202,1207,1229,1237,1275,1276,1313,1314,1319,1320,1321,1345,1347,1351,1357,1365,1380,1410);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 4
SET pe.active = o.acceptance
WHERE pe.profileID = 4;

SELECT 'Done: endorsements for profileID=4' AS status;